INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (590, 1, '루프백의 IPv6 주소', '`ip -6 addr show lo` 는 `lo` 의 IPv6 주소를 보여 줍니다. IPv6 의 루프백 주소(자기 자신)를 **접두어 길이 포함**해서(`주소/길이`) `/tmp/lo6.txt` 에 저장하세요.', '`inet6` 으로 시작하는 줄의 둘째 칸입니다.', 'ip -6 addr show lo
ip -6 addr show lo | grep inet6 | awk ''{print $2}'' | head -1 > /tmp/lo6.txt
cat /tmp/lo6.txt

# IPv6 루프백은 ::1 이고 접두어는 /128(주소 하나)이다. IPv4 의 127.0.0.1 에 해당한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/ip6.log <<''EOF''\\n2: eth0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 state UP\\n    inet6 2001:db8:10:1::a/64 scope global\\n    inet6 2001:db8:10:1:5054:ff:fe12:3456/64 scope global dynamic mngtmpaddr\\n    inet6 fe80::5054:ff:fe12:3456/64 scope link\\nEOF\\ncat > /tmp/route6.log <<''EOF''\\n2001:db8:10:1::/64 dev eth0 proto kernel metric 256\\nfe80::/64 dev eth0 proto kernel metric 256\\ndefault via fe80::1 dev eth0 metric 1024\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/lo6.txt)\\" = \\"::1/128\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "::1/128 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/lo6.txt)\\" = \\"::1/128\\" ]"]}]', '[{"title": "IPv6 주소 지정(RFC 4291)", "url": "https://www.rfc-editor.org/rfc/rfc4291"}, {"title": "ip 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}]'),
  (590, 2, 'ping -6 으로 확인', '자기 자신의 IPv6 주소로 응답이 오는지 **3번** 보내 보고, **받은 응답 수**를 숫자만 `/tmp/recv.txt` 에 저장하세요. (IPv4 가 아니라 IPv6 로 보내야 합니다)', '`ping` 에 주소 체계를 고르는 옵션과 횟수를 정하는 옵션이 있습니다. 요약 줄의 `received` 앞 숫자를 뽑으세요.', 'ping -6 -c 3 ::1
ping -6 -c 3 ::1 | grep -o ''[0-9]* received'' | cut -d'' '' -f1 > /tmp/recv.txt
cat /tmp/recv.txt

# ping6 도 같은 동작이다. IPv6 에서는 ICMPv6 가 이웃 탐색(NDP) 등에 필수라 무조건 차단하면 통신이 깨진다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/ip6.log <<''EOF''\\n2: eth0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 state UP\\n    inet6 2001:db8:10:1::a/64 scope global\\n    inet6 2001:db8:10:1:5054:ff:fe12:3456/64 scope global dynamic mngtmpaddr\\n    inet6 fe80::5054:ff:fe12:3456/64 scope link\\nEOF\\ncat > /tmp/route6.log <<''EOF''\\n2001:db8:10:1::/64 dev eth0 proto kernel metric 256\\nfe80::/64 dev eth0 proto kernel metric 256\\ndefault via fe80::1 dev eth0 metric 1024\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/recv.txt)\\" = 3 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "3 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/recv.txt)\\" = 3 ]"]}]', '[{"title": "IPv6 주소 지정(RFC 4291)", "url": "https://www.rfc-editor.org/rfc/rfc4291"}, {"title": "ip 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}]'),
  (590, 3, '주소를 가장 짧게 쓰기', 'IPv6 주소는 앞자리 0 을 생략하고, 연속된 0 묶음을 `::` 로 **한 번만** 줄여 쓸 수 있습니다. `2001:0db8:0000:0000:0000:0000:0000:0001` 을 **가장 짧은 표기**로 `/tmp/short.txt` 에 저장하세요. (소문자)', '각 묶음 앞의 0 은 지우고, 모두 0 인 묶음이 이어진 가장 긴 구간을 `::` 하나로 바꾸세요.', 'echo ''2001:db8::1'' > /tmp/short.txt
cat /tmp/short.txt

# 0 묶음이 두 군데 이상 있으면 가장 긴 쪽을 ::로 줄이고 :: 는 주소 안에 한 번만 쓸 수 있다. 2001:db8::/32 는 문서용 대역이다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/ip6.log <<''EOF''\\n2: eth0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 state UP\\n    inet6 2001:db8:10:1::a/64 scope global\\n    inet6 2001:db8:10:1:5054:ff:fe12:3456/64 scope global dynamic mngtmpaddr\\n    inet6 fe80::5054:ff:fe12:3456/64 scope link\\nEOF\\ncat > /tmp/route6.log <<''EOF''\\n2001:db8:10:1::/64 dev eth0 proto kernel metric 256\\nfe80::/64 dev eth0 proto kernel metric 256\\ndefault via fe80::1 dev eth0 metric 1024\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/short.txt)\\" = \\"2001:db8::1\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "2001:db8::1 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/short.txt)\\" = \\"2001:db8::1\\" ]"]}]', '[{"title": "IPv6 주소 지정(RFC 4291)", "url": "https://www.rfc-editor.org/rfc/rfc4291"}, {"title": "ip 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}]'),
  (590, 4, 'link-local 주소 찾기', '`/tmp/ip6.log` 는 서버의 `ip -6 addr` 출력 일부입니다. `fe80::/10` 으로 시작하는 **link-local 주소**는 같은 링크 안에서만 쓰이고 라우터를 넘지 못합니다. 이 서버의 link-local 주소를 **접두어 길이 없이** `/tmp/ll.txt` 에 저장하세요.', '`scope link` 가 붙은 줄을 찾고, 주소에서 `/` 뒤를 떼세요.', 'cat /tmp/ip6.log
grep ''scope link'' /tmp/ip6.log | awk ''{print $2}'' | cut -d/ -f1 > /tmp/ll.txt
cat /tmp/ll.txt

# link-local 은 인터페이스를 켜면 자동으로 생긴다. 이웃 탐색과 라우터 광고, 기본 게이트웨이 지정에 쓰인다. 다른 대역으로는 전달되지 않는다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/ip6.log <<''EOF''\\n2: eth0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 state UP\\n    inet6 2001:db8:10:1::a/64 scope global\\n    inet6 2001:db8:10:1:5054:ff:fe12:3456/64 scope global dynamic mngtmpaddr\\n    inet6 fe80::5054:ff:fe12:3456/64 scope link\\nEOF\\ncat > /tmp/route6.log <<''EOF''\\n2001:db8:10:1::/64 dev eth0 proto kernel metric 256\\nfe80::/64 dev eth0 proto kernel metric 256\\ndefault via fe80::1 dev eth0 metric 1024\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/ll.txt)\\" = \\"fe80::5054:ff:fe12:3456\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "fe80::5054:ff:fe12:3456 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/ll.txt)\\" = \\"fe80::5054:ff:fe12:3456\\" ]"]}]', '[{"title": "IPv6 주소 지정(RFC 4291)", "url": "https://www.rfc-editor.org/rfc/rfc4291"}, {"title": "ip 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}]'),
  (590, 5, '전역 주소 개수', '같은 `/tmp/ip6.log` 에서 인터넷·사내망에서 통하는 **전역(global) 주소**가 **몇 개**인지 숫자만 `/tmp/global.txt` 에 저장하세요. 이 서버의 `eth0` 에는 고정 주소와 자동 설정된 주소가 함께 있습니다.', '`scope global` 이 붙은 줄을 세세요. `scope link` 는 제외합니다.', 'grep -c ''scope global'' /tmp/ip6.log > /tmp/global.txt
cat /tmp/global.txt

# 한 인터페이스에 IPv6 주소가 여러 개인 것은 정상이다. dynamic 은 라우터 광고(SLAAC)로 자동 생성된 주소다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/ip6.log <<''EOF''\\n2: eth0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 state UP\\n    inet6 2001:db8:10:1::a/64 scope global\\n    inet6 2001:db8:10:1:5054:ff:fe12:3456/64 scope global dynamic mngtmpaddr\\n    inet6 fe80::5054:ff:fe12:3456/64 scope link\\nEOF\\ncat > /tmp/route6.log <<''EOF''\\n2001:db8:10:1::/64 dev eth0 proto kernel metric 256\\nfe80::/64 dev eth0 proto kernel metric 256\\ndefault via fe80::1 dev eth0 metric 1024\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/global.txt)\\" = 2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "2 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/global.txt)\\" = 2 ]"]}]', '[{"title": "IPv6 주소 지정(RFC 4291)", "url": "https://www.rfc-editor.org/rfc/rfc4291"}, {"title": "ip 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}]'),
  (590, 6, '기본 게이트웨이는 link-local', '`/tmp/route6.log` 는 `ip -6 route` 의 출력입니다. IPv6 의 기본 경로는 라우터의 **link-local 주소**를 게이트웨이로 가리키는 경우가 많습니다. 기본 경로(`default`)의 **게이트웨이 주소**를 `/tmp/gw6.txt` 에 저장하세요. (주소만)', '`default` 줄에서 `via` 바로 다음 칸입니다.', 'cat /tmp/route6.log
grep ''^default'' /tmp/route6.log | awk ''{print $3}'' > /tmp/gw6.txt
cat /tmp/gw6.txt

# fe80::1 은 같은 링크의 라우터다. link-local 주소는 인터페이스마다 겹칠 수 있어 dev eth0 와 함께 읽어야 의미가 정해진다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/ip6.log <<''EOF''\\n2: eth0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 state UP\\n    inet6 2001:db8:10:1::a/64 scope global\\n    inet6 2001:db8:10:1:5054:ff:fe12:3456/64 scope global dynamic mngtmpaddr\\n    inet6 fe80::5054:ff:fe12:3456/64 scope link\\nEOF\\ncat > /tmp/route6.log <<''EOF''\\n2001:db8:10:1::/64 dev eth0 proto kernel metric 256\\nfe80::/64 dev eth0 proto kernel metric 256\\ndefault via fe80::1 dev eth0 metric 1024\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/gw6.txt)\\" = \\"fe80::1\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "fe80::1 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/gw6.txt)\\" = \\"fe80::1\\" ]"]}]', '[{"title": "IPv6 주소 지정(RFC 4291)", "url": "https://www.rfc-editor.org/rfc/rfc4291"}, {"title": "ip 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}]'),
  (590, 7, 'NDP 와 ARP', 'IPv4 에서 같은 링크의 상대 MAC 주소를 알아내는 데 ARP 를 씁니다. IPv6 에서 이 역할을 하는 것은?', '이름에 이웃(neighbor)이 들어가는 프로토콜입니다.', NULL, NULL, '[]', 'choice', '["DHCPv6 서버가 MAC 주소를 알려 준다", "브로드캐스트로 보내는 ARP 요청 그대로 사용", "ICMPv6 기반의 이웃 탐색(NDP)", "DNS 서버가 MAC 주소를 알려 준다"]', 2, 'IPv6 에는 브로드캐스트가 없고 ARP 대신 ICMPv6 의 이웃 탐색(Neighbor Discovery)이 같은 역할(주소 해석, 라우터 발견, 중복 주소 탐지)을 합니다. 그래서 ICMPv6 를 통째로 차단하면 통신이 깨집니다.', NULL, NULL, NULL, NULL),
  (590, 8, 'SLAAC 로 자동 설정', '라우터가 광고하는 접두어(/64)와 인터페이스 정보로 서버가 **스스로 주소를 만들어** 설정하는 방식을 무엇이라 할까요?', 'DHCP 서버 없이도 주소가 만들어집니다.', NULL, NULL, '[]', 'choice', '["NAT64(IPv6 와 IPv4 사이의 주소 변환)", "SLAAC (상태 비저장 주소 자동 설정)", "DHCPv6 만 가능한 서버 기반 고정 할당", "ARP 스푸핑(위조 응답으로 주소 가로채기)"]', 1, 'SLAAC 은 라우터 광고(RA)의 접두어에 인터페이스 식별자를 붙여 주소를 자동 생성합니다. DHCPv6 는 서버가 주소·옵션을 알려 주는 방식이고 둘을 함께 쓰기도 합니다. NAT64 는 IPv6↔IPv4 변환 기술입니다.', NULL, NULL, NULL, NULL),
  (590, 9, '이중 스택에서의 지연', '서버가 IPv4 와 IPv6 를 모두 쓰는 이중 스택인데, 어떤 서비스 이름이 AAAA(IPv6)와 A(IPv4) 레코드를 모두 가집니다. IPv6 경로가 중간에서 막혀 있으면 어떤 일이 생기기 쉬울까요?', 'AAAA 와 A 중 어느 쪽을 먼저 쓰는지, 막힌 경로는 어떻게 실패하는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["IPv6 시도가 시간 초과된 뒤 IPv4 로 넘어가 연결이 느려진다", "두 주소를 동시에 써서 항상 더 빨라진다", "IPv6 가 막혀 있으면 DNS 가 AAAA 를 자동으로 삭제한다", "연결이 어떤 경우에도 완전히 불가능해진다"]', 0, '클라이언트는 AAAA 를 먼저 시도하는 경우가 많아, IPv6 경로가 막혀 있으면 시간 초과를 기다린 뒤 IPv4 로 폴백해 처음 연결이 느려집니다(Happy Eyeballs 가 이를 줄입니다). IPv6 를 쓰지 않으면 AAAA 를 내지 않거나 경로를 제대로 열어야 합니다.', NULL, NULL, NULL, NULL),
  (590, 10, 'IPv6 주소만 보기', '`lo` 의 주소 중 **IPv6 주소만** 보려 합니다. 빈칸에 들어갈 `ip` 옵션을 채우세요.', '`ip` 의 옵션 중 주소 체계(IPv4·IPv6)를 고르는 글자입니다.', NULL, NULL, '[]', 'fill', '["6", "4", "s", "c"]', NULL, '`-6` 은 IPv6 주소만, `-4` 는 IPv4 주소만 보여 줍니다. `-s` 는 통계(카운터)를, `-c` 는 색 출력을 켜는 옵션이라 두 가지 모두 주소를 가려 보여 주지 않습니다.', '[0]', 'ip -{0} addr show lo', NULL, NULL);
